const BASE = 'https://n8n.checkintrust.com/webhook';
const EXT_TOKEN = 'edl_wh_7Kx2mPn9sRtL';
const DOCUSEAL_TOKEN = 'FtrjsZSaBdPdeZBTdhxbRTTXUMwV5gh6WFNqbBCbZTu';
const helpers = this.helpers;

const results = [];

async function test(name, fn) {
  try {
    await fn();
    results.push({ test: name, status: 'PASS' });
  } catch (e) {
    results.push({ test: name, status: 'FAIL', error: e.message });
  }
}

// Helper : GET avec récupération du statusCode sans throw sur 4xx
async function safeGet(url, extraHeaders) {
  try {
    const r = await helpers.httpRequest({ method: 'GET', url, headers: extraHeaders || {}, returnFullResponse: true });
    return { statusCode: r.statusCode || 200, body: r.body };
  } catch (e) {
    const code = e.statusCode || parseInt((e.message || '').match(/\b(\d{3})\b/)?.[1]) || 0;
    return { statusCode: code, error: e.message };
  }
}

// Helper : POST avec récupération du statusCode sans throw sur 4xx
async function safePost(url, body) {
  try {
    const r = await helpers.httpRequest({
      method: 'POST', url,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      returnFullResponse: true
    });
    return { statusCode: r.statusCode || 200, body: r.body };
  } catch (e) {
    const code = e.statusCode || parseInt((e.message || '').match(/\b(\d{3})\b/)?.[1]) || 0;
    return { statusCode: code, error: e.message };
  }
}

// T1: Agent 0 — accessible avec token valide
await test('Agent 0 — Token valide → liste retournée', async () => {
  const r = await safeGet(`${BASE}/edl-locataires?t=${EXT_TOKEN}`);
  if (r.statusCode !== 200) throw new Error(`HTTP ${r.statusCode}`);
  const data = Array.isArray(r.body) ? r.body : JSON.parse(r.body);
  if (!Array.isArray(data)) throw new Error('Format invalide : tableau attendu');
  if (data.length === 0) throw new Error('Liste vide — vérifier Notion');
});

// T2: Agent 0 — rejet sans token
await test('Agent 0 — Token manquant → 401', async () => {
  const r = await safeGet(`${BASE}/edl-locataires`);
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T3: Agent 6 — rejet token invalide
await test('Agent 6 — Token invalide → 401', async () => {
  const r = await safePost(`${BASE}/edl-secure`, { _token: 'MAUVAIS_TOKEN', meta: {}, pieces: {} });
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T4: Agent 6 — rejet schéma invalide (token ok mais schéma ko)
await test('Agent 6 — Schéma invalide → 401', async () => {
  const r = await safePost(`${BASE}/edl-secure`, { _token: EXT_TOKEN, meta: { type: 'INVALIDE', chambre: 999 }, pieces: {} });
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T5: DocuSeal — API accessible
await test('DocuSeal — API accessible', async () => {
  const r = await safeGet('https://docuseal.checkintrust.com/api/templates?limit=1', { 'X-Auth-Token': DOCUSEAL_TOKEN });
  if (r.statusCode !== 200) throw new Error(r.error || `HTTP ${r.statusCode}`);
});

const passed = results.filter(r => r.status === 'PASS').length;
const total = results.length;
return [{ json: {
  summary: `${passed}/${total} tests passés`,
  passed, total,
  allPassed: passed === total,
  results,
  timestamp: new Date().toISOString()
} }];

